; start.asm -- 3com-pktdrv cold entry + JIT composer (fully assembly, no C runtime).
;
; The driver is a single self-specializing TSR (docs/02). At load, COLD code detects the
; machine, then COMPOSES the hot path from position-independent fragments (build/frags_asm.inc,
; generated by tools/mkfrag.py from src/asm/frag/*.asm), baking decisions in as immediates.
; copy-down then packs the emitted image and DOS-keeps it; everything here is reclaimed.
;
; This file is the cold orchestration + composer. It must itself be 8088-clean (it runs on
; a 5150). The emitted hot path is the fragments, not this code.
;
; Build: nasm -f obj -> wlink (system dos). Entry point is ..start. No C, no C library.

cpu 8086
bits 16

%include "codegen.inc"
; EL3 register constants are pulled per-generation by the probe (el3_probe.asm includes
; el3_tomahawk.inc -> el3_core.inc); start.asm proper needs none directly.

;==============================================================================
; DATA (initialized) -- fragment palette, plan template
;==============================================================================
segment _DATA public class=DATA use16

%include "frags_asm.inc"        ; f_*[], *_patches[], g_frags[], FRAG_TABLE_N

; The emit plan for a 3C509B (PIO floor): the fragment ids to compose, each followed by its
; immediate-0 (io_base for the PIO datapath steps; 0 for the rest). build_plan() fills the
; io_base slots from the detected NIC. Layout per step: db id ; dw imm0  (3 bytes).
g_plan:
    db FRAG_API_DISPATCH
    dw 0
    db FRAG_ISR_ENTRY
    dw 0
    db FRAG_RX_PIO
g_plan_rx_imm:
    dw 0
    db FRAG_TX_PIO
g_plan_tx_imm:
    dw 0
    db FRAG_ISR_EOI
    dw 0
G_PLAN_N        equ 5
PLAN_STEP_SIZE  equ 3

; diagnostic strings ($-terminated for INT 21h AH=09h)
msg_banner  db '3com-pktdrv floor (3C509 packet driver)', 13, 10, '$'
msg_cpu     db 'CPU class=', '$'
msg_nic     db 13, 10, '3C509 I/O=0x', '$'
msg_irq     db ' IRQ=0x', '$'
msg_mac     db ' MAC=', '$'
msg_no_nic  db 13, 10, 'No 3C509 found', 13, 10, '$'
msg_crlf    db 13, 10, '$'

;==============================================================================
; BSS (uninitialized) -- runtime state + the emit destination
;==============================================================================
segment _BSS public class=BSS use16

psp_seg:        resw 1          ; PSP segment (saved at entry, for the TSR keep)
g_cpu_class:    resb 1          ; CPU_8088 .. CPU_P6 (set by detect_cpu)
                resb 1
g_nic_io:       resw 1          ; detected 3C509B I/O base
g_nic_irq:      resw 1          ; detected IRQ
g_mac:          resb 6          ; station address (from EEPROM)
g_emitted_len:  resw 1
g_keep_para:    resw 1

; composer scratch
g_pos:          resw 1          ; current write offset into resident_image
g_planptr:      resw 1
g_step:         resw 1
g_imm0:         resw 1
g_curid:        resb 1
                resb 1

; entry offsets of each emitted fragment (0xFFFF if not emitted); install reads
; g_off[FRAG_API_DISPATCH] and g_off[FRAG_ISR_ENTRY].
g_off:          resw FRAG__COUNT

; the composed hot image (copy-down packs it; DOS-keeps up to here)
resident_image: resb 512

;==============================================================================
; STACK -- in DGROUP so SS == DS (small model). The cold composer's working stack;
; the resident TSR sets up its own stack when install lands.
;==============================================================================
segment _STACK stack class=STACK use16
        resb 1024

;==============================================================================
; CODE
;
; _TEXT is in DGROUP (tiny model): CS = DS = ES = SS = DGROUP, one addressable segment, so
; the resident INT 60h handler / ISR (next milestone) can NEAR-call the emitted datapath in
; resident_image. The _BSS + _STACK tail is uninitialized -> minalloc, not stored in the file.
;==============================================================================
group DGROUP _TEXT _DATA _BSS _STACK
segment _TEXT public class=CODE use16

..start:
        mov     bp, es              ; ES = PSP at .EXE entry -- save for the TSR keep
        mov     ax, DGROUP
        mov     ds, ax
        mov     es, ax              ; composer uses ES:DI for the emit destination
        mov     [psp_seg], bp

        mov     dx, msg_banner
        call    print_str

        call    detect_cpu          ; -> g_cpu_class
        mov     dx, msg_cpu
        call    print_str
        mov     al, [g_cpu_class]
        add     al, '0'
        call    print_char          ; CPU class digit (0=8088,1=286,2=386)

        ; --- 5150 short-circuit -------------------------------------------------
        ; On an 8088/8086 the DMA capability axis collapses to PIO: no protected mode,
        ; no >1 MB / XMS, no bus-master, no VMM. So we skip the entire test-before-trust
        ; and environment machinery (busmaster test, cache-coherency tier, VDS/V86 probe,
        ; PCI/EISA/MCA/PCMCIA bus probers) and take the floor path straight to the PIO
        ; compose. On >=286 those cold phases run (added as the ladder is climbed).
        cmp     byte [g_cpu_class], CPU_8088
        jbe     .floor
        call    phase_platform_probe    ; (>=286) V86/VDS/memory tiers      [stub]
        call    phase_validate_dma      ; (>=286) busmaster test + cache    [stub]
.floor:
        ; ISA NIC detection. The native 3Com ID-port sequence is the universal EtherLink III
        ; ISA mechanism and runs on ANY CPU -- it's just port I/O. ISA PnP is a SEPARATE
        ; software protocol over fixed ports (0x279/0xA79 + relocatable read) that ALSO works
        ; on any ISA bus: it is NOT CPU-dependent (no PnP BIOS or 286+ needed to run the
        ; isolation -- a software PnP manager does it). PnP only matters for a 3C509B left in
        ; PnP-only mode or already claimed by a PnP BIOS, so it is a FULL-PROFILE add
        ; (CFG_PNP), compiled out of the minimal floor for size -- gated by profile, not CPU.
        call    detect_nic          ; native 3Com ID-port (Tomahawk) -> g_nic_io/irq/mac
%ifdef CFG_PNP
        jnc     .nic_found          ; native found a card
        call    detect_nic_pnp      ; else (full profile) try ISA PnP (cache-kit isapnp)
%endif
        jc      .nic_none           ; no card found
.nic_found:
        mov     dx, msg_nic         ; "3C509 I/O=0x"
        call    print_str
        mov     ax, [g_nic_io]
        call    print_hex16
        mov     dx, msg_irq         ; " IRQ=0x"
        call    print_str
        mov     ax, [g_nic_irq]
        call    print_hex16
        call    print_mac           ; " MAC=xx:xx:.."
        mov     dx, msg_crlf
        call    print_str

        call    el3_init            ; bring the activated card to operational state
        call    build_plan          ; copy io_base into the plan's PIO steps

        call    compose_resident    ; ax = emitted length, fills resident_image + g_off
        or      ax, ax
        jz      .fail
        mov     [g_emitted_len], ax

        call    copy_down           ; ax = paragraphs to keep
        mov     [g_keep_para], ax

        ; TODO(next): install INT 60h + NIC IRQ from g_off[], then DOS TSR-keep.
        ; Deferred while the API/ISR fragments are stubs. Terminate cleanly for now.
        mov     ax, 0x4C00
        int     0x21
.nic_none:
        mov     dx, msg_no_nic
        call    print_str
.fail:
        mov     ax, 0x4C01
        int     0x21

;------------------------------------------------------------------------------
; detect_cpu -- classify 8086/8088 vs 286 vs 386+ via the FLAGS 12-15 test.
; 8088-safe (no push-immediate). Sets g_cpu_class. Coarse by design: the floor only
; needs 8088 vs >=286; finer 486/Pentium/CPUID detail is added with their fragments.
;------------------------------------------------------------------------------
detect_cpu:
        pushf
        pop     ax
        mov     cx, ax              ; save original FLAGS
        and     ax, 0x0FFF          ; try to clear bits 12-15
        push    ax
        popf
        pushf
        pop     ax
        and     ax, 0xF000
        cmp     ax, 0xF000          ; stuck high? -> 8086/8088
        je      .is8088
        or      cx, 0xF000          ; try to set bits 12-15
        push    cx
        popf
        pushf
        pop     ax
        and     ax, 0xF000
        jz      .is286              ; stuck low -> 286
        mov     byte [g_cpu_class], CPU_80386   ; settable -> 386+ (coarse)
        ret
.is286:
        mov     byte [g_cpu_class], CPU_80286
        ret
.is8088:
        mov     byte [g_cpu_class], CPU_8088
        ret

;------------------------------------------------------------------------------
; phase stubs (>=286 cold phases; real logic lands as the ladder is climbed)
;------------------------------------------------------------------------------
phase_platform_probe:
        ret
phase_validate_dma:
        ret

; detect_nic / id_read_eeprom / io_delay -- the real 3C509B ISA probe + activation.
%include "el3_probe.asm"

; el3_init -- operational bring-up of the activated card (MAC, media, RX/TX enable).
%include "el3_init.asm"

;------------------------------------------------------------------------------
; build_plan -- the HAL hands the composer the NIC's immediates: io_base into the PIO
; datapath steps. (Equivalent of the old c509b_emit_plan.)
;------------------------------------------------------------------------------
build_plan:
        mov     ax, [g_nic_io]
        mov     [g_plan_rx_imm], ax
        mov     [g_plan_tx_imm], ax
        ret

;------------------------------------------------------------------------------
; compose_resident -- select + stitch + patch the planned fragments into resident_image.
; Records each fragment's landing offset in g_off[]. 8088-clean (movsb/stosw/loops).
; out: AX = emitted length (0 on missing fragment / over budget).
;------------------------------------------------------------------------------
compose_resident:
        ; g_off[] = 0xFFFF
        mov     di, g_off
        mov     cx, FRAG__COUNT
        mov     ax, 0xFFFF
        rep     stosw                   ; ES:DI (= DGROUP)

        mov     word [g_pos], 0
        mov     word [g_planptr], g_plan
        mov     word [g_step], G_PLAN_N
.step:
        mov     si, [g_planptr]
        mov     al, [si]                ; frag id
        mov     [g_curid], al
        inc     si
        mov     ax, [si]                ; imm0
        mov     [g_imm0], ax
        add     si, 2
        mov     [g_planptr], si

        mov     al, [g_curid]
        call    frag_lookup             ; -> DI = entry, CF=1 if none
        jc      .fail

        ; g_off[id] = pos
        mov     bl, [g_curid]
        xor     bh, bh
        shl     bx, 1
        mov     ax, [g_pos]
        mov     [g_off + bx], ax

        ; copy fragment bytes: resident_image[pos..] = entry.bytes[0..len)
        mov     cx, [di + 4]            ; len
        mov     si, [di + 6]            ; src ptr
        push    di
        mov     di, resident_image
        add     di, [g_pos]
        rep     movsb                   ; DS:SI -> ES:DI
        pop     di

        ; apply immediate patches (floor: all PATCH_IMM16 = io_base)
        xor     ch, ch
        mov     cl, [di + 2]            ; n_patches
        jcxz    .nopatch
        mov     si, [di + 8]            ; patch table ptr
.patch:
        mov     bx, [si]                ; patch.offset (within fragment)
        add     bx, [g_pos]
        mov     ax, [g_imm0]
        mov     [resident_image + bx], ax
        add     si, PATCH_ENTRY_SIZE
        loop    .patch
.nopatch:
        mov     ax, [di + 4]            ; pos += len
        add     [g_pos], ax

        dec     word [g_step]
        jnz     .step

        mov     ax, [g_pos]
        ret
.fail:
        xor     ax, ax
        ret

;------------------------------------------------------------------------------
; frag_lookup -- find the best fragment for (id=AL, class=g_cpu_class): matching id with
; the highest cpu_min that is <= the detected class. out: DI = entry, CF=0; CF=1 if none.
; clobbers BX, CX, DX (and DI).
;------------------------------------------------------------------------------
frag_lookup:
        mov     di, g_frags
        mov     cx, FRAG_TABLE_N
        xor     bx, bx                  ; bx = best entry (0 = none yet)
        xor     dl, dl                  ; dl = best cpu_min
.fl_loop:
        cmp     [di], al                ; entry.id == id?
        jne     .fl_next
        mov     dh, [di + 1]            ; entry.cpu_min
        cmp     dh, [g_cpu_class]
        ja      .fl_next                ; cpu_min > class -> not emittable
        or      bx, bx
        jz      .fl_take                ; first match
        cmp     dh, dl
        jbe     .fl_next                ; not a higher cpu_min than current best
.fl_take:
        mov     bx, di
        mov     dl, dh
.fl_next:
        add     di, FRAG_ENTRY_SIZE
        loop    .fl_loop

        or      bx, bx
        jz      .fl_none
        mov     di, bx
        clc
        ret
.fl_none:
        stc
        ret

;------------------------------------------------------------------------------
; copy_down -- floor: the image was composed in place in resident_image (no relocs in the
; PIO floor fragments), so this just reports the size in paragraphs. Real packing + reloc
; fixups arrive with cross-fragment references. in: AX = emitted len; out: AX = paragraphs.
;------------------------------------------------------------------------------
copy_down:
        add     ax, 15
        mov     cl, 4
        shr     ax, cl                  ; ceil(len / 16)
        ret

;------------------------------------------------------------------------------
; Diagnostic print helpers (COLD; DOS INT 21h). Clobber AX/CX/DX freely.
;------------------------------------------------------------------------------
print_str:                              ; DS:DX -> '$'-terminated string
        mov     ah, 9
        int     0x21
        ret
print_char:                             ; AL = character
        mov     dl, al
        mov     ah, 2
        int     0x21
        ret
print_hex16:                            ; AX = value -> 4 hex digits
        push    ax
        mov     al, ah
        call    print_hex8
        pop     ax
        call    print_hex8
        ret
print_hex8:                             ; AL = byte -> 2 hex digits
        push    ax
        mov     cl, 4
        shr     al, cl                  ; high nibble
        call    print_nib
        pop     ax                      ; low nibble (print_nib masks)
        call    print_nib
        ret
print_nib:                              ; AL low nibble -> hex char
        and     al, 0x0F
        add     al, '0'
        cmp     al, '9'
        jbe     .e
        add     al, 7                   ; 'A'..'F'
.e:
        mov     dl, al
        mov     ah, 2
        int     0x21
        ret
print_mac:                              ; " MAC=" + g_mac[0..5] as hex
        mov     dx, msg_mac
        call    print_str
        mov     si, g_mac
        mov     cx, 6
.pm:
        push    cx
        lodsb
        call    print_hex8
        pop     cx
        loop    .pm
        ret
